mapper.select:
select FIN_PRODUCT.FINPROD_MARKET_ID id, FIN_PRODUCT.FINPROD_ABBR text, FIN_PRODUCT.FINPROD_ID object from FIN_PRODUCT INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_PRODUCT.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} where FIN_PRODUCT.FINPROD_TYPE2 IN
#{item,jdbcType=VARCHAR}
AND (FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) OR FIN_PRODUCT.FINPROD_ABBR like concat('%',concat(#{search},'%')))
AND FIN_PRODUCT.FINPROD_MARKET_ID = #{initValue}

select FIN_PRODUCT.FINPROD_MARKET_ID id, FIN_PRODUCT.FINPROD_ABBR text, FIN_PRODUCT.FINPROD_ID object,
case when FIN_PRODUCT.PROFIT_TYPE = #{profitType_02} then #{YES_OR_NO_N} when FIN_PRODUCT_ADD.DEAL_MODE = #{dealMode_10} then #{YES_OR_NO_N} else FIN_PRODUCT_ADD.IS_LAY end as col
from FIN_PRODUCT INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_PRODUCT.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
FIN_PRODUCT.FINPROD_TYPE2 = #{args0,jdbcType=VARCHAR}
AND FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%'))
AND FIN_PRODUCT.FINPROD_MARKET_ID = #{initValue}

select FIN_PRODUCT.FINPROD_ABBR, FIN_PRODUCT.FINPROD_MARKET_ID, FIN_CASH_INFO.CASH_ID CASH_ID_STR, MST_FEEINFO.FEE_NAME, MST_FEEINFO.FEE_TYPE, PRD_LAYER_PARAM.PROD_STYLE FROM FIN_CASH_INFO, MST_FEEINFO,FIN_PRODUCT LEFT JOIN PRD_LAYER_PARAM ON FIN_PRODUCT.FINPROD_ID = PRD_LAYER_PARAM.FINPROD_ID where FIN_PRODUCT.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} AND FIN_PRODUCT.FINPROD_TYPE = #{finprodType2,jdbcType=VARCHAR} AND FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID AND MST_FEEINFO.CHARGE_TYPE = #{chargeType01,jdbcType=VARCHAR} AND FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR} AND FIN_CASH_INFO.CASH_TYPE_2 IN
#{item,jdbcType=VARCHAR}
AND FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID

select FIN_PRODUCT.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, FIN_CASH_INFO.CASH_ID cashId, FIN_CASH_INFO.CASH_ID cashIdStr, MST_FEEINFO.FEE_NAME feeName, MST_FEEINFO.FEE_TYPE feeType, FIN_CASH_CALC_RULE.EFF_DATE effDate,
FIN_CASH_CALC_RULE.YIELD*100 yield, FIN_CASH_CALC_RULE.REMARK remark, PRD_LAYER_PARAM.PROD_STYLE from FIN_CASH_CALC_RULE, FIN_CASH_INFO, MST_FEEINFO, FIN_PRODUCT LEFT JOIN PRD_LAYER_PARAM ON FIN_PRODUCT.FINPROD_ID = PRD_LAYER_PARAM.FINPROD_ID where FIN_PRODUCT.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} AND FIN_PRODUCT.FINPROD_TYPE = #{finprodType2,jdbcType=VARCHAR} AND FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID AND FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR} AND FIN_CASH_INFO.CASH_TYPE_2 IN
#{item,jdbcType=VARCHAR}
AND FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID AND FIN_CASH_INFO.CASH_ID = FIN_CASH_CALC_RULE.CASH_ID AND FIN_CASH_INFO.CASH_ID = #{cashId,jdbcType=VARCHAR} AND FIN_CASH_CALC_RULE.EFF_DATE = #{effDate,jdbcType=DATE}
AND PRD_LAYER_PARAM.PROD_STYLE = #{prodStyle}

select FIN_PRODUCT.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, FIN_CASH_INFO.CASH_ID cashId, MST_FEEINFO.FEE_NAME feeName, MST_FEEINFO.FEE_TYPE feeType, FIN_CASH_CALC_RULE.EFF_DATE effDate,
FIN_CASH_CALC_RULE.YIELD yield, FIN_CASH_CALC_RULE.REMARK remark from FIN_PRODUCT, FIN_CASH_CALC_RULE, FIN_CASH_INFO, MST_FEEINFO where FIN_PRODUCT.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} AND FIN_PRODUCT.FINPROD_TYPE = #{finprodType2,jdbcType=VARCHAR} AND FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID AND FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR} AND FIN_CASH_INFO.CASH_TYPE_2 IN
#{item,jdbcType=VARCHAR}
AND FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID AND FIN_CASH_INFO.CASH_ID = FIN_CASH_CALC_RULE.CASH_ID AND FIN_CASH_CALC_RULE.EFF_DATE = #{effDate,jdbcType=DATE}
AND FIN_CASH_INFO.CASH_ID = #{cashId,jdbcType=VARCHAR}


SELECT distinct
	   PRD_LAYER_PARAM.PROD_STYLE id,
       PRD_LAYER_PARAM.PROD_STYLE text,
       PRD_LAYER_PARAM.FINPROD_ID object
 FROM PRD_LAYER_PARAM,FIN_CASH_INFO
WHERE PRD_LAYER_PARAM.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID
 AND FIN_CASH_INFO.CASH_TYPE_1 =#{cashType1_03}

 	AND PRD_LAYER_PARAM.P_FINPROD_ID = #{pfinprodId}


 	AND PRD_LAYER_PARAM.PROD_STYLE = #{initValue}
